# owner: platform
"""Lay students out in rows, ordered by last name."""

from operator import attrgetter
from typing import Iterable, List

from rosterkit.models import Student

def check_seating(
    students: List[Student], per_row: int
) -> None:
    if per_row <= 0:
        raise ValueError("seats per row must be positive")
    if not students:
        raise ValueError("no students to seat")

def split_rows(
    ordered: List[Student], per_row: int
) -> List[List[Student]]:
    starts = range(0, len(ordered), per_row)
    return [
        ordered[start:start + per_row] for start in starts
    ]

def row_line(number: int, members: List[Student]) -> str:
    names = " | ".join(
        member.display_name for member in members
    )
    return f"Row {number}: {names}"

def row_lines(groups: List[List[Student]]) -> List[str]:
    numbered = enumerate(groups, 1)
    return [
        row_line(number, members)
        for number, members in numbered
    ]

def seating_rows(
    students: Iterable[Student], per_row: int
) -> List[str]:
    """One line per row, students sorted by last name."""
    ordered = sorted(students, key=attrgetter("last_name"))
    check_seating(ordered, per_row)
    return row_lines(split_rows(ordered, per_row))

