# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.seating import seating_rows

def make_student(last_name, first_name):
    return Student("0", last_name, first_name, "A")

class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make_student("Halloway", "Juno"),
            make_student("Quillon", "Sefa"),
            make_student("Dunmere", "Piet"),
        ]

    def test_rows_follow_last_name_order(self):
        rows = seating_rows(self.students, 2)
        expected = "Row 1: Dunmere, Piet | Halloway, Juno"
        self.assertEqual(rows[0], expected)
        self.assertEqual(rows[1], "Row 2: Quillon, Sefa")

    def test_one_seat_per_row_is_one_line_each(self):
        rows = seating_rows(self.students, 1)
        self.assertEqual(len(rows), 3)

    def test_zero_seats_is_rejected(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, 0)

    def test_negative_seats_is_rejected(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, -2)

    def test_no_students_is_rejected(self):
        with self.assertRaises(ValueError):
            seating_rows([], 2)
